tape( 'the function supports view offsets', opts, function test( t ) {
	var expected;
	var out;
	var x0;
	var x1;
	var y0;
	var y1;

	// Row-major:
	x0 = new Complex64Array( [ 0.0, 0.0, 1.0, 2.0, 3.0, 4.0 ] );
	x1 = new Complex64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );

	y0 = new Complex64Array( [ 0.0, 0.0, 5.0, 6.0, 7.0, 8.0 ] );
	y1 = new Complex64Array( y0.buffer, y0.BYTES_PER_ELEMENT*1 );

	out = new Complex64Array( 8 );
	expected = new Complex64Array([
		1.0,
		2.0,
		5.0,
		6.0,
		1.0,
		2.0,
		7.0,
		8.0,
		3.0,
		4.0,
		5.0,
		6.0,
		3.0,
		4.0,
		7.0,
		8.0
	]);

	ccartesianProduct( 'row-major', 2, 2, x1, 1, y1, 1, out, 2 );
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );

	// Column-major:
	x0 = new Complex64Array( [ 0.0, 0.0, 1.0, 2.0, 3.0, 4.0 ] );
	x1 = new Complex64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );

	y0 = new Complex64Array( [ 0.0, 0.0, 5.0, 6.0, 7.0, 8.0 ] );
	y1 = new Complex64Array( y0.buffer, y0.BYTES_PER_ELEMENT*1 );

	out = new Complex64Array( 8 );
	expected = new Complex64Array([
		1.0,
		2.0,
		1.0,
		2.0,
		3.0,
		4.0,
		3.0,
		4.0,
		5.0,
		6.0,
		7.0,
		8.0,
		5.0,
		6.0,
		7.0,
		8.0
	]);

	ccartesianProduct( 'column-major', 2, 2, x1, 1, y1, 1, out, 4 );
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );

	t.end();
});
